   if high<=low or not dp[i]:continue
   vals=[a[k] for k in range(i+1,j) if low<a[k]<high]
   m=len(vals); suf=[0]*(m+1)
   for k in range(m-1,-1,-1):suf[k]=max(suf[k+1],vals[k])
   mn=n+1
   for k,v in enumerate(vals):
    if mn>v>suf[k+1]:break
    if v<mn:mn=v
   else:total+=dp[i]
  dp[j]=total%MOD
