def brute(p):
 n=len(p); adj=[sum(1<<j for j in range(n) if (i-j)*(p[i]-p[j])>0) for i in range(n)]
 seen={(1<<n)-1}; stack=list(seen)
 while stack:
  s=stack.pop()
  for i in range(n):
   if s>>i&1:
    t=s&~adj[i]
    if t not in seen:seen.add(t);stack.append(t)
