import sys

MOD = 998244353

def main():
    data = iter(map(int, sys.stdin.buffer.read().split()))
    n = next(data)
    m = next(data)

    # bound[l][x] is the smallest right endpoint of a condition
    # targeting x whose left endpoint is at least l.
    bound = [[n] * n for _ in range(n)]
    for _ in range(m):
        l = next(data) - 1
        r = next(data) - 1
        x = next(data) - 1
        if l == r:
            print(0)
            return
        if r < bound[l][x]:
            bound[l][x] = r

    for l in range(n - 2, -1, -1):
        row = bound[l]
        following = bound[l + 1]
        for x in range(l + 1, n):
            if following[x] < row[x]:
                row[x] = following[x]

    inv = [0] * (n + 1)
    inv[1] = 1
    for i in range(2, n + 1):
        inv[i] = MOD - (MOD // i) * inv[MOD % i] % MOD

    # dp[l][end] counts valid relative permutations on [l,end),
    # divided by (end-l)! modulo MOD.
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][i] = 1

    for l in range(n - 1, -1, -1):
        row = dp[l]
        limits = bound[l]
        for end in range(l + 1, n + 1):
            r = end - 1
            total = 0
            for x in range(l, end):
                if r < limits[x]:
                    total += row[x] * dp[x + 1][end]
            row[end] = total % MOD * inv[end - l] % MOD

    factorial = 1
    for i in range(2, n + 1):
        factorial = factorial * i % MOD
    print(dp[0][n] * factorial % MOD)

if __name__ == '__main__':
    main()

