import sys
from collections import deque

MOD = 998244353


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    a = [v - 1 for v in data[2:]]
    degree = [0] * n
    for v in a:
        degree[v] += 1

    queue = deque(i for i in range(n) if degree[i] == 0)
    dp = [None] * n

    # Remove trees towards their cycles. None denotes an all-one row.
    while queue:
        u = queue.popleft()
        v = a[u]
        row = dp[u]
        target = dp[v]
        if row is None:
            if target is None:
                dp[v] = list(range(1, m + 1))
            else:
                for j in range(m):
                    target[j] = target[j] * (j + 1) % MOD
        else:
            prefix = 0
            if target is None:
                for j in range(m):
                    prefix = (prefix + row[j]) % MOD
                    row[j] = prefix
                dp[v] = row
            else:
                for j in range(m):
                    prefix = (prefix + row[j]) % MOD
                    target[j] = target[j] * prefix % MOD
            dp[u] = None
        degree[v] -= 1
        if degree[v] == 0:
            queue.append(v)

    answer = 1
    for i in range(n):
        if degree[i] == 0:
            continue
        u = i
        total = None
        # All vertices of a cycle must have the same value.
        while degree[u]:
            degree[u] = 0
            row = dp[u]
            if row is not None:
                if total is None:
                    total = row
                else:
                    for j in range(m):
                        total[j] = total[j] * row[j] % MOD
            u = a[u]
        ways = m if total is None else sum(total) % MOD
        answer = answer * ways % MOD
    print(answer)


if __name__ == '__main__':
    main()

