import sys
from math import gcd
MOD = 998244353

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n = data[0]
    factors = {}
    for i, x in enumerate(data[1:]):
        p = 2
        while p * p <= x:
            if x % p == 0:
                e = 0
                while x % p == 0:
                    x //= p
                    e += 1
                if p not in factors:
                    factors[p] = [0] * (n - 1)
                factors[p][i] = e
            p += 1
        if x > 1:
            if x not in factors:
                factors[x] = [0] * (n - 1)
            factors[x][i] = 1

    ans = 1
    for p, es in factors.items():
        g = 0
        for e in es:
            g = gcd(g, e)
        es = [e // g for e in es]
        base = pow(p, g, MOD)
        total = sum(es)
        powers = [1] * (total + 1)
        for j in range(total):
            powers[j + 1] = powers[j] * base % MOD

        # Normalize each partial exponent sequence to have minimum zero.
        # dp[h] sums its weights when the final exponent is h.
        dp = [1]
        s = 0
        for i, e in enumerate(es, 1):
            if e == 0:
                dp = [v * powers[j] % MOD for j, v in enumerate(dp)]
                continue
            ns = s + e
            nd = [0] * (ns + 1)
            for j in range(1, min(e - 1, s - e) + 1):
                nd[j] = dp[j + e] * powers[j] % MOD
            for j in range(e, s - e + 1):
                nd[j] = (dp[j - e] + dp[j + e]) * powers[j] % MOD
            for j in range(max(e, s - e + 1), ns + 1):
                nd[j] = dp[j - e] * powers[j] % MOD

            # A step below zero raises all i previous exponents.
            t = pow(base, i, MOD)
            w = 1
            v = 0
            for h in range(e, -1, -1):
                if h <= s:
                    v += dp[h] * w
                w = w * t % MOD
            nd[0] = v % MOD
            dp = nd
            s = ns
        ans = ans * sum(dp) % MOD
    print(ans)

if __name__ == '__main__':
    solve()

