    for _ in range(q):
        t = next(it)
        if t == 1:
            e = next(it)-1
            closed[e] = True
            queries.append((1, e))
        else:
            queries.append((2, next(it)-1, next(it)-1))

    inf = 10**18
    d = [[inf]*n for _ in range(n)]
    for i in range(n):
        d[i][i] = 0
    for e, (a, b, w) in enumerate(edges):
        if not closed[e]:
            d[a][b] = d[b][a] = w

    for k in range(n):
        dk = d[k]
        for i in range(n):
            di = d[i]
            v = di[k]
            if v == inf:
                continue
            for j in range(n):
                z = v + dk[j]
                if z < di[j]:
                    di[j] = z

    ans = []
    for query in reversed(queries):
        if query[0] == 2:
            z = d[query[1]][query[2]]
            ans.append(str(z if z < inf else -1))
        else:
            a, b, w = edges[query[1]]
            if w >= d[a][b]:
                continue
            da = d[a][:]
            db = d[b][:]
            for i in range(n):
                if da[i] + w < db[i]:
                    offset = da[i] + w
                    other = db
                elif db[i] + w < da[i]:
                    offset = db[i] + w
                    other = da
                else:
                    continue
                di = d[i]
                for j in range(i+1, n):
                    z = offset + other[j]
                    if z < di[j]:
                        di[j] = z
                        d[j][i] = z

    sys.stdout.write('\n'.join(reversed(ans)))

