class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        mod = 10**9 + 7
        dp = [0] * (min(n, x) + 1)
        dp[0] = 1
        factors = [0] + [(x - k + 1) * y for k in range(1, len(dp))]
        for i in range(1, n + 1):
            for k in range(min(i, x), 0, -1):
                dp[k] = (k * dp[k] + factors[k] * dp[k - 1]) % mod
            dp[0] = 0
        return sum(dp) % mod

