class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        length = len(s)

        # dp[w]: already-smaller prefixes containing exactly w set bits.
        dp = [0] * (length + 1)
        prefix_ones = 0
        for i, bit in enumerate(s):
            # Extend already-smaller prefixes by either zero or one.
            for w in range(i + 1, 0, -1):
                dp[w] = (dp[w] + dp[w - 1]) % MOD
            if bit == '1':
                # Choose zero here, departing from the equal prefix.
                dp[prefix_ones] = (dp[prefix_ones] + 1) % MOD
                prefix_ones += 1

        depth = [0] * (length + 1)
        for w in range(2, length + 1):
            depth[w] = depth[w.bit_count()] + 1

        return sum(dp[w] for w in range(1, length + 1)
                   if depth[w] < k) % MOD

