import sys


def best(active, pending_even=0, pending_odd=0):
    # Active sums are divisible by the current power of two.
    # Pending sums had their least significant 1 at the previous bit;
    # the bit chosen now determines their crease types.
    if len(active) <= 1:
        return max(pending_even, pending_odd) + len(active)

    even = []
    odd = []
    c0 = c1 = c2 = c3 = 0
    for x in active:
        r = x & 3
        if x & 1:
            odd.append((x + 1) >> 1)
            if r == 1:
                c1 += 1
            else:
                c3 += 1
        else:
            even.append(x >> 1)
            if r == 0:
                c0 += 1
            else:
                c2 += 1

    choose_zero = pending_odd + best(even, c1, c3)
    choose_one = pending_even + best(odd, c0, c2)
    return max(choose_zero, choose_one)


