def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[:2]
    rows = [0] * n
    for i in range(m):
        u, v = data[2+2*i]-1, data[3+2*i]-1
        rows[u] |= 1 << v
        rows[v] |= 1 << u
    pivots = []
    rank = 0
    for c in range(n):
        bit = 1 << c
        p = next((i for i in range(rank, n) if rows[i] & bit), -1)
        if p == -1:
            continue
        rows[rank], rows[p] = rows[p], rows[rank]
        r = rows[rank]
        for i in range(n):
            if i != rank and rows[i] & bit:
                rows[i] ^= r
        pivots.append(c)
        rank += 1
