    free = [i for i in range(n) if i not in pivot_set]
    ans = [0] * n
    for k, c in enumerate(free):
        ans[c] = 1 << k
        for i, p in enumerate(pivots):
            if rows[i] & (1 << c):
                ans[p] |= 1 << k
