class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        odd, even = (n + 1) // 2, n // 2
        total = fact[odd] * fact[even] * (2 if n % 2 == 0 else 1)
        if k > total:
            return []

        remaining = list(range(1, n + 1))
        result = []
        required = 1 if n % 2 else -1

        for _ in range(n):
            for i, value in enumerate(remaining):
                parity = value % 2
                if required != -1 and parity != required:
                    continue

                next_odd = odd - parity
                next_even = even - (1 - parity)
                ways = fact[next_odd] * fact[next_even]
                if k > ways:
                    k -= ways
                else:
                    result.append(value)
                    remaining.pop(i)
                    odd, even = next_odd, next_even
                    required = 1 - parity
                    break

