import sys
from bisect import bisect_left

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    n=data[0]
    a=data[1:n+1]; b=data[n+1:2*n+1]; c=data[2*n+1:]
    down=[]; up=[]; common=[]
    for x,y,w in zip(a,b,c):
        if x and not y: down.append(w)
        elif y and not x: up.append(w)
        elif x and y: common.append(w)
    down.sort(); up.sort(); common.sort(reverse=True)
    d=len(down); u=len(up)
    pd=[0]
    for w in down: pd.append(pd[-1]+w)
    pu=[0]
    for w in up: pu.append(pu[-1]+w)
    f=sum((d-1-i)*w for i,w in enumerate(down))+sum((u-i)*w for i,w in enumerate(up))
    s=sum(common)
    m=d+u
    ans=m*s+f
    for k,w in enumerate(common):
        p=bisect_left(down,w); q=bisect_left(up,w)
        f+=(d-p+k)*w+pd[p]+(u-q+k+1)*w+pu[q]
        s-=w
        cost=(m+2*k+2)*s+f
        if cost<ans: ans=cost
    print(ans)

