from math import gcd

class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        powers = [1] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k
        half = (n + 1) // 2
        weights = [0] * half
        for i in range(half):
            j = n - 1 - i
            weights[i] = powers[i] % k if i == j else (powers[i] + powers[j]) % k
        suffix = [k] * (half + 1)
        for i in range(half - 1, -1, -1):
            suffix[i] = gcd(suffix[i + 1], weights[i])
        digits = []
        remainder = 0
        for i, weight in enumerate(weights):
            g = suffix[i + 1]
            for digit in range(9, -1, -1):
                value = remainder + digit * weight
                if value % g == 0:
                    digits.append(str(digit))
                    remainder = value % k
                    break
        left = ''.join(digits)
        return left + (left[:-1] if n % 2 else left)[::-1]

