def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, k = data[0], data[1]

    counts = {}
    for i in range(2, 2 * n + 2, 2):
        pair = (data[i], data[i + 1])
        counts[pair] = counts.get(pair, 0) + 1

    # Process functions from innermost to outermost.
    def compare(p, q):
        return (p[0] - 1) * q[1] - (q[0] - 1) * p[1]

    pairs = sorted(counts, key=cmp_to_key(compare))
    dp = [-1] * (k + 1)
    dp[0] = 1
    seen = 0

    for a, b in pairs:
        # More than k copies of an identical function cannot be needed.
        for _ in range(min(k, counts[(a, b)])):
            seen += 1
            for j in range(min(k, seen), 0, -1):
                value = a * dp[j - 1] + b
                if value > dp[j]:
