class Solution:
    def maximumSubarrayXor(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        grouped = [[] for _ in range(n)]
        for k, (l, r) in enumerate(queries):
            grouped[l].append((r, k))
        answer = [0] * len(queries)
        score = [0] * n
        best = [0] * n
        for l in range(n - 1, -1, -1):
            score[l] = nums[l]
            best[l] = nums[l]
            for r in range(l + 1, n):
                value = score[r] ^ score[r - 1]
                score[r] = value
                top = best[r]
                if best[r - 1] > top:
                    top = best[r - 1]
                if value > top:
                    top = value
                best[r] = top
            for r, k in grouped[l]:
                answer[k] = best[r]
        return answer

class Solution:
    def makeStringGood(self, s: str) -> int:
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - 97] += 1
        answer = len(s)
        for target in range(1, max(counts) + 1):
            dp0 = dp1 = 0
            previous = 0
            for count in counts:
                best = min(dp0, dp1)
                new0 = best + count
                if count >= target:
                    new1 = best + count - target
                else:
                    deficit = target - count
                    surplus = max(previous - target, 0)
                    new1 = deficit + min(dp0 - min(previous, deficit), dp1 - min(surplus, deficit))
                dp0, dp1 = new0, new1
                previous = count
            answer = min(answer, dp0, dp1)
        return answer

