MOD = 998244353


def solve(h, w, grid):
    n = h + w
    parent = list(range(n))
    size = [1] * n
    parity = [0] * n
    cols = [0] * w
    components = n

    def find(x):
        p = 0
        while parent[x] != x:
            p ^= parity[x]
            x = parent[x]
        return x, p

    for i, row in enumerate(grid):
        r = 0
        for j, c in enumerate(row):
            if c == 65:
                r ^= 1
                cols[j] ^= 1
            else:
