                b, pb = find(h + j)
                v = 1 ^ r ^ cols[j] ^ pa ^ pb
                if a == b:
                    if v:
                        return 0
                else:
                    if size[a] < size[b]:
                        a, b = b, a
                    parent[b] = a
                    parity[b] = v
                    size[a] += size[b]
                    components -= 1
        if r:
            return 0

    if any(cols):
        return 0
    return pow(2, components, MOD)


