        if minimum > n:
            return -1

        def occurrences(t):
            m = len(t)
            if m == 0:
                return range(n + 1)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            result = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    result.append(i - m + 1)
                    j = pi[j - 1]
            return result

        aa, bb, cc = occurrences(a), occurrences(b), occurrences(c)
        j = k = 0
        nb, nc = len(bb), len(cc)
        best = n + 1
        for start in aa:
            end_a = start + la
            while j < nb and bb[j] < end_a:
                j += 1
            if j == nb:
                break
            end_b = bb[j] + lb
            while k < nc and cc[k] < end_b:
                k += 1
            if k == nc:
                break
            length = cc[k] + lc - start
            if length < best:
