import sys

def solve(n, a, b):
    if a == b:
        return 0
    ap = [i + 1 for i, c in enumerate(a) if c == 49]
    bp = [i + 1 for i, c in enumerate(b) if c == 49]
    m = len(ap)
    h = len(bp)
    if h > m:
        return -1
    if h == 1:
        return max(abs(ap[0] - bp[0]), abs(ap[-1] - bp[0]))
    runs = []
    prev = 0
    for x in ap:
        if x > prev + 1:
            runs.append((prev, x - 1))
        prev = x
    runs.append((prev, 4 * n + 10))
    items = [(bp[i], bp[i + 1] - bp[i] - 1) for i in range(h - 1)]
    items.append((bp[-1], n - bp[-1]))
    first = ap[0]
    last = ap[-1]
    nr = len(runs)
    last_index = h - 1
    first_target = bp[0]

    def check(t):
        end = first_target - 1 - t
        if end >= first:
            return False
        j = z = 0
        for idx, (pos, k) in enumerate(items):
            while j < m and ap[j] <= end:
                j += 1
            if j == m:
                return False
            x = last if idx == last_index else ap[j]
            p = x + ((x - pos + t) & 1)
            if k:
                while z < nr:
                    l, r = runs[z]
                    q = p if p >= l else l
                    q += (q - pos + t) & 1
                    if q + k <= r:
                        p = q
                        break
                    z += 1
                else:
                    return False
            if p > pos + t:
                return False
            end = p + k
        return True

    def possible(t):
        return check(t) or (t > 0 and check(t - 1))

    lower = max(abs(first - bp[0]), abs(last - bp[-1]))
    if possible(lower):
        return lower
    hi = 2 * n
    if not possible(hi):
        return -1
    lo = lower
    while hi - lo > 1:
        mid = (lo + hi) // 2
        if possible(mid):
            hi = mid
        else:
            lo = mid
    return hi

def main():
    inp = sys.stdin.buffer
    t = int(inp.readline())
    out = []
    for _ in range(t):
        n = int(inp.readline())
        a = inp.readline().strip()
        b = inp.readline().strip()
        out.append(str(solve(n, a, b)))
    sys.stdout.write('\n'.join(out))

