import heapq


def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, W = data[:2]
    groups = [[] for _ in range(W + 1)]
    for i in range(2, len(data), 2):
        w, v = data[i], data[i + 1]
        if v > 1:
            groups[w].append(1 - v)

    dp = [0] * (W + 1)
    for w in range(1, W + 1):
        heap = groups[w]
        if not heap:
            continue
        heapq.heapify(heap)
        vals = []
        for _ in range(W // w):
            v = -heap[0]
            if v <= 0:
                break
            vals.append(v)
            heapq.heapreplace(heap, 2 - v)

        K = len(vals)
        if K <= 12:
            for v in vals:
                for j in range(W, w - 1, -1):
                    x = dp[j - w] + v
                    if x > dp[j]:
                        dp[j] = x
        else:
            gain = [0]
            for v in vals:
                gain.append(gain[-1] + v)

            for r in range(min(w, W - w + 1)):
                a = dp[r::w]
                m = len(a) - 1
                b = a.copy()

                def calc(l, h, ol, oh):
                    if l > h:
                        return
                    t = (l + h) // 2
                    start = max(ol, t - K)
                    end = min(oh, t)
                    best = -1
                    arg = start
                    for j in range(start, end + 1):
                        x = a[j] + gain[t - j]
                        if x > best:
                            best = x
                            arg = j
                    b[t] = best
                    calc(l, t - 1, ol, arg)
                    calc(t + 1, h, arg, oh)

                calc(1, m, 0, m)
                dp[r::w] = b

    print(dp[W])


