import sys


def main():
    data = sys.stdin.buffer.read().split()
    k = int(data[0])
    s, t = data[1], data[2]
    n, m = len(s), len(t)
    if abs(n - m) > k:
        print('No')
        return

    def extend(x, y):
        remaining = min(n - x, m - y)
        if remaining <= 0 or s[x] != t[y]:
            return x
        step = 1
        while step <= remaining and s[x:x + step] == t[y:y + step]:
            x += step
            y += step
            remaining -= step
            step <<= 1
        step >>= 1
        while step:
            if step <= remaining and s[x:x + step] == t[y:y + step]:
                x += step
                y += step
                remaining -= step
            step >>= 1
        return x

    x = extend(0, 0)
    if n == m and x == n:
        print('Yes')
        return

    prev = {0: x}
    target = n - m
    for edits in range(1, k + 1):
        cur = {}
        low = max(-edits, target - (k - edits))
        high = min(edits, target + (k - edits))
        for d in range(low, high + 1):
            best = -1
            for old_d, advance in ((d - 1, 1), (d, 1), (d + 1, 0)):
                old_x = prev.get(old_d)
                if old_x is None:
                    continue
                x = old_x + advance
                y = x - d
                if 0 <= x <= n and 0 <= y <= m and x > best:
                    best = x
            if best < 0:
                continue
            x = extend(best, best - d)
            if d == target and x == n:
                print('Yes')
                return
            cur[d] = x
        prev = cur
    print('No')


if __name__ == '__main__':
    main()

