class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        mod = 1000000007
        counts = [0] * 26
        for ch in s:
            counts[ord(ch) - 97] += 1
        first = 0
        for _ in range(t):
            last = first - 1 if first else 25
            counts[first] = (counts[first] + counts[last]) % mod
            first = last
        return sum(counts) % mod

