class Solution:
    def countPairs(self, nums: List[int]) -> int:
        seen = {}
        answer = 0

        # Processing smaller numbers first also handles leading-zero swaps.
        for x in sorted(nums):
            digits = list(map(int, str(x)))
            length = len(digits)
            powers = [10 ** (length - 1 - i) for i in range(length)]
            reachable = {x}

            for i in range(length):
                for j in range(i + 1, length):
                    reachable.add(
                        x + (digits[j] - digits[i]) * (powers[i] - powers[j])
                    )

            answer += sum(seen.get(y, 0) for y in reachable)
            seen[x] = seen.get(x, 0) + 1

        return answer

