from typing import List

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        answer = 0
        for i, target in enumerate(nums):
            if target == 0:
                continue

            # Bit s is set exactly when a subset of processed, covering
            # queries can decrement this position by s.
            reachable = 1
            goal = 1 << target
            mask = (goal << 1) - 1

            for k, (left, right, value) in enumerate(queries, 1):
                if left <= i <= right:
                    reachable = (reachable | (reachable << value)) & mask
                    if reachable & goal:
                        answer = max(answer, k)
                        break
            else:
                return -1

        return answer

