from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0
        a = bytes(nums)

        # Z values identify which initial subarrays repeat immediately.
        z = [0] * n
        left = right = 0
        for i in range(1, n):
            length = min(right - i + 1, z[i - left]) if i <= right else 0
            while i + length < n and a[length] == a[i + length]:
                length += 1
            z[i] = length
            if i + length - 1 > right:
                left, right = i, i + length - 1

        good = [False] * n
        answer = 0
        for i in range(1, (n - 1) // 2 + 1):
            if z[i] >= i:
                good[i] = True
                answer += n - 2 * i

        # Fix the length k of the second subarray. A backward scan
        # tracks how many consecutive entries match at distance k.
        for k in range(1, (n - 1) // 2 + 1):
            run = 0
            for i in range(n - k - 1, 0, -1):
                if a[i] == a[i + k]:
                    run += 1
                    if run >= k and (i > k or not good[i]):
                        answer += 1
                else:
                    run = 0
        return answer

