class Solution:
    def maxActiveSectionsAfterTrade(self, s: str) -> int:
        active = s.count('1')
        previous = 0
        best_gain = 0

        # Consecutive nonempty zero runs surround a removable one run.
        # Removing it and filling the merged zero run gains exactly
        # the combined lengths of those two original zero runs.
        for block in s.split('1'):
            if block:
                length = len(block)
                if previous:
                    best_gain = max(best_gain, previous + length)
                previous = length

        return active + best_gain

