                earliest = min(last.values())
                if earliest >= left:
                    total += earliest - left + 1
            return total
        return at_most(k) - at_most(k - 1)

class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        def at_most(limit):
            if limit < 0:
                return 0
            last = dict.fromkeys('aeiou', -1)
            left = consonants = total = 0
            for right, ch in enumerate(word):
                if ch in last:
                    last[ch] = right
                else:
                    consonants += 1
                while consonants > limit:
                    if word[left] not in last:
                        consonants -= 1
                    left += 1
                earliest = min(last.values())
                if earliest >= left:
                    total += earliest - left + 1
            return total
        return at_most(k) - at_most(k - 1)

