class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        present = {tuple(p) for p in points}
        best = -1
        for x1, y1 in points:
            for x2, y2 in points:
                if x1 >= x2 or y1 >= y2:
                    continue
                if (x1, y2) not in present or (x2, y1) not in present:
                    continue
                count = 0
                for x, y in points:
                    if x1 <= x <= x2 and y1 <= y <= y2:
                        count += 1
                if count == 4:
                    best = max(best, (x2 - x1) * (y2 - y1))
        return best

